_purchasely_complete() {
  local cur="${COMP_WORDS[COMP_CWORD]}" path="" i w
  for ((i = 1; i < COMP_CWORD; i++)); do
    w="${COMP_WORDS[i]}"
    case " $(_purchasely_subs "$path") " in *" $w "*) path="${path:+$path }$w" ;; esac
  done
  COMPREPLY=($(compgen -W "$(_purchasely_subs "$path") $(_purchasely_opts "$path")" -- "$cur"))
}
complete -F _purchasely_complete purchasely
